window.docContents[65].resolve({"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Formal-Decorated-Programs--More-Automation":{"contents":"The propositions generated by DCom.VerificationConditions are fairly\nbig and contain many conjuncts that are essentially trivial.\n\nexample : decWhile.VerificationConditions := by\n  rw [Decorated.VerificationConditions, decWhile]\n  simp only [DCom.VerificationConditions,\n    DCom.postcondition]\n\n\n\n\nFortunately, our verify_assertion tactic can generally take care of\nmost (or sometimes all) of them.\n\nexample : decWhile.VerificationConditions := by\n  simp only [decWhile]\n  verify_assertion\n\n\n\n\nTo automate the overall process of verification, we can use\nverification_conditions_correct to extract the verification conditions, use the logic of verify_assertion to verify them as much as it can, and finally tidy up any remaining bits by hand.\n\n-- Adapted from One An's `hoare2-meluge-pass`.\n\n-- These boolean comparisons\n-- in guards simplify straight to propositions rather than to\n-- `decide (…) = true`, whose `Decidable` instance `simp` leaves behind.\ntheorem Bexp.eval_le_true {st : State} {a₁ a₂ : Aexp} :\n    (Bexp.le a₁ a₂).eval st = true ↔ a₁.eval st ≤ a₂.eval st := by\n  simp\n\ntheorem Bexp.eval_le_false {st : State} {a₁ a₂ : Aexp} :\n    (Bexp.le a₁ a₂).eval st = false ↔ ¬ a₁.eval st ≤ a₂.eval st := by\n  simp\n\ntheorem Bexp.eval_gt_true {st : State} {a₁ a₂ : Aexp} :\n    (Bexp.gt a₁ a₂).eval st = true ↔ a₁.eval st > a₂.eval st := by\n  simp\n\ntheorem Bexp.eval_gt_false {st : State} {a₁ a₂ : Aexp} :\n    (Bexp.gt a₁ a₂).eval st = false ↔ ¬ a₁.eval st > a₂.eval st := by\n  simp\n\n\n-- Unlike `verify_assertion`, this leaves any conjunct `lia` cannot\n-- prove open as a separate goal.\nmacro \"verify\" : tactic =>\n  `(tactic|\n    (apply verification_conditions_correct;\n     simp +decide [-Bexp.eval_le, -Bexp.eval_gt,\n       Bexp.eval_le_true, Bexp.eval_le_false,\n       Bexp.eval_gt_true, Bexp.eval_gt_false,\n       assertImplies_def, assertIff_def,\n       validHoareTriple_def, Assertion.subst_def];\n     all_goals and_intros;\n     all_goals try lia))\n\n\n\n\nHere's the final, formal proof that decWhile is correct.\n\ntheorem dec_while_correct : decWhile.OuterTripleValid := by\n  simp only [decWhile]\n  verify\n\n\nSimilarly, here is the formal decorated program for the \"swapping\nby adding and subtracting\" example that we saw earlier.def swapDec (m n : Nat) : Decorated where\n  pre := ({{ X = m ∧ Y = n }})\n  body := dcom {\n    ↠ {{ (X + Y) - ((X + Y) - Y) = n ∧ (X + Y) - Y = m }}\n    X := X + Y {{ X - (X - Y) = n ∧ X - Y = m }};\n    Y := X - Y {{ X - Y = n ∧ Y = m }};\n    X := X - Y {{ X = n ∧ Y = m }}\n  }\n\ntheorem swap_correct (m n : Nat) :\n    (swapDec m n).OuterTripleValid := by\n  simp only [swapDec]\n  verify\nAnd here is the formal decorated version of the \"positive\ndifference\" program from earlier:def positiveDifferenceDec : Decorated where\n  pre := ({{ True }})\n  body := dcom {\n    if (X ≤ Y) then\n      {{ True ∧ X ≤ Y }}\n      ↠ {{ (Y - X) + X = Y ∨ (Y - X) + Y = X }}\n      Z := Y - X {{ Z + X = Y ∨ Z + Y = X }}\n    else\n      {{ True ∧ ¬ X ≤ Y }}\n      ↠ {{ (X - Y) + X = Y ∨ (X - Y) + Y = X }}\n      Z := X - Y {{ Z + X = Y ∨ Z + Y = X }}\n    end\n      {{ Z + X = Y ∨ Z + Y = X }}\n  }\n\ntheorem positive_difference_correct :\n    positiveDifferenceDec.OuterTripleValid := by\n  simp only [positiveDifferenceDec]\n  verify\nHere is a skeleton of the formal decorated version of the\nif_minus_plus program that we saw earlier.  Replace all\noccurrences of FILL_IN_HERE with appropriate assertions and fill\nin the proof (which should be just as straightforward as in the\nexamples above).def ifMinusPlusDec : Decorated where\n  pre := ({{ True }})\n  body := dcom {\n    if (X ≤ Y) then\n      {{ True ∧ X ≤ Y }}\n      ↠ {{ Y = X + (Y - X) }}\n      Z := Y - X {{ Y = X + Z }}\n    else\n      {{ True ∧ ¬ X ≤ Y }}\n      ↠ {{ X + Z = X + Z }}\n      Y := X + Z {{ Y = X + Z }}\n    end\n      {{ Y = X + Z }}\n  }\n\ntheorem if_minus_plus_correct :\n    ifMinusPlusDec.OuterTripleValid := by\n  solution!\n    simp only [ifMinusPlusDec]\n    verify\nFill in appropriate assertions for the division program from above.def divModDec (a b : Nat) : Decorated where\n  pre := ({{ True }})\n  body := dcom {\n    ↠ {{ b * 0 + a = a }}\n    X := ~(Aexp.num a) {{ b * 0 + X = a }};\n    Y := 0 {{ b * Y + X = a }};\n    while (~(Aexp.num b) ≤ X) do\n      {{ b * Y + X = a ∧ b ≤ X }}\n      ↠ {{ b * (Y + 1) + (X - b) = a }}\n      X := X - ~(Aexp.num b) {{ b * (Y + 1) + X = a }};\n      Y := Y + 1 {{ b * Y + X = a }}\n    end\n      {{ b * Y + X = a ∧ ¬ b ≤ X }}\n    ↠ {{ b * Y + X = a ∧ X < b }}\n  }\n\ntheorem div_mod_outer_triple_valid (a b : Nat) :\n    (divModDec a b).OuterTripleValid := by\n  solution!\n    simp only [divModDec]\n    verify\n\n\n","context":"Hoare Logic\u0009Hoare2: Hoare Logic, Part II\u0009Formal Decorated Programs","header":"6.2.3. More Automation","id":"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Formal-Decorated-Programs--More-Automation"}});